properties.query:
let TriggeredIPs =
SecurityAlert
| where DisplayName contains "GO-PRD-SENTINEL-050 VPN Brute Force Attack followed by Successful Access"
| where TimeGenerated >= ago(24h)
| extend A = parse_json(Entities)
| mvexpand A
| extend IP = tostring(A.Address)
| where isnotempty(IP)
| summarize make_list(IP);
let timeframe = 5m;
let threshold = 3;
let FirewallVendor = "Cisco";
let FirewallProduct = "ASA";
let FWLogs=() {
CommonSecurityLog1
| where TimeGenerated >= ago(timeframe)
| where DeviceVendor =~ FirewallVendor and DeviceProduct =~ FirewallProduct 
};
let FailedUsers = 
FWLogs
| extend UserName = case( Message contains "user authentication Rejected", tostring(split(split(Message, ":")[4], "=")[1]) 
			 			 ,Message contains "User authentication failed", tostring(split(Message, ":")[4]) 
                         , ""
						)
| where isnotempty(UserName)
| summarize count() by UserName, DeviceAddress
| where count_ >= threshold
| summarize make_list(UserName);
//See if any of these users have sucessfully logged in
let SucceededUser = 
FWLogs
| where Message contains "User authentication succeeded"
| extend UserName = tostring(split(Message, ":")[4])
| where UserName in (FailedUsers)
| extend SourceIp = extract("(([0-9]{1,3})\\.([0-9]{1,3})\\.([0-9]{1,3})\\.(([0-9]{1,3})))",1,Message)
| where SourceIp !in (TriggeredIPs)
| extend Threat = strcat(UserName, " succeeded after ", threshold, " failures" );
SucceededUser
| extend timestamp = TimeGenerated, AccountCustomEntity = UserName, IPCustomEntity = SourceIp
